shader_type canvas_item;

uniform float u_amplitude : hint_range(0.0, 3.0) = 1.0;
uniform float u_blend : hint_range(0.0, 1.0) = 0.5;
uniform vec3 u_color_stop_a : source_color = vec3(0.3216, 0.1529, 1.0);
uniform vec3 u_color_stop_b : source_color = vec3(0.4863, 1.0, 0.4039);
uniform vec3 u_color_stop_c : source_color = vec3(0.3216, 0.1529, 1.0);

vec3 permute(vec3 x) {
    return mod(((x * 34.0) + 1.0) * x, 289.0);
}

float snoise(vec2 v) {
    const vec4 C = vec4(
        0.211324865405187,
        0.366025403784439,
        -0.577350269189626,
        0.024390243902439
    );
    vec2 i = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);

    vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

    vec3 m = max(
        0.5 - vec3(
            dot(x0, x0),
            dot(x12.xy, x12.xy),
            dot(x12.zw, x12.zw)
        ),
        0.0
    );
    m = m * m;
    m = m * m;

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

    vec3 g;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

vec3 color_ramp(float t) {
    if (t <= 0.5) {
        float f = smoothstep(0.0, 0.5, t);
        return mix(u_color_stop_a, u_color_stop_b, f);
    }

    float f = smoothstep(0.5, 1.0, t);
    return mix(u_color_stop_b, u_color_stop_c, f);
}

void fragment() {
    vec2 uv = SCREEN_UV;
    vec3 ramp_color = color_ramp(uv.x);

    float height = snoise(vec2(uv.x * 2.0 + TIME * 0.1, TIME * 0.25)) * 0.5 * u_amplitude;
    height = exp(height);
    height = uv.y * 2.0 - height + 0.2;
    float intensity = 0.6 * height;

    float mid_point = 0.20;
    float aurora_alpha = smoothstep(mid_point - u_blend * 0.5, mid_point + u_blend * 0.5, intensity);
    vec3 aurora_color = intensity * ramp_color;

    COLOR = vec4(aurora_color * aurora_alpha, aurora_alpha);
}

shader_type canvas_item;

uniform float u_spin_rotation : hint_range(-10.0, 10.0) = -2.0;
uniform float u_spin_speed : hint_range(0.0, 20.0) = 7.0;
uniform float u_contrast : hint_range(0.5, 8.0) = 3.5;
uniform float u_lighting : hint_range(0.0, 2.0) = 0.4;
uniform float u_spin_amount : hint_range(0.0, 1.0) = 0.25;
uniform vec3 u_color1 : source_color = vec3(0.8706, 0.2667, 0.2314);
uniform vec3 u_color2 : source_color = vec3(0.0, 0.4196, 0.7059);
uniform vec3 u_color3 : source_color = vec3(0.0863, 0.1373, 0.1451);

vec3 effect(vec2 screen_size, vec2 screen_coords) {
    float pixel_filter = 745.0;
    float spin_ease = 1.0;
    vec2 offset = vec2(0.0, 0.0);

    float pixel_size = length(screen_size) / pixel_filter;
    vec2 uv = (floor(screen_coords * (1.0 / pixel_size)) * pixel_size - 0.5 * screen_size) / length(screen_size) - offset;
    float uv_len = length(uv);

    float speed = u_spin_rotation * spin_ease * 0.2 + 302.2;
    float new_pixel_angle = atan(uv.y, uv.x) + speed - spin_ease * 20.0 * (u_spin_amount * uv_len + (1.0 - u_spin_amount));
    vec2 mid = (screen_size / length(screen_size)) / 2.0;
    uv = vec2(uv_len * cos(new_pixel_angle) + mid.x, uv_len * sin(new_pixel_angle) + mid.y) - mid;

    uv *= 30.0;
    speed = TIME * u_spin_speed;
    vec2 uv2 = vec2(uv.x + uv.y);

    for (int i = 0; i < 5; i++) {
        uv2 += sin(max(uv.x, uv.y)) + uv;
        uv += 0.5 * vec2(
            cos(5.1123314 + 0.353 * uv2.y + speed * 0.131121),
            sin(uv2.x - 0.113 * speed)
        );
        uv -= cos(uv.x + uv.y) - sin(uv.x * 0.711 - uv.y);
    }

    float safe_contrast = max(u_contrast, 0.001);
    float contrast_mod = 0.25 * safe_contrast + 0.5 * u_spin_amount + 1.2;
    float paint_res = min(2.0, max(0.0, length(uv) * 0.035 * contrast_mod));
    float c1p = max(0.0, 1.0 - contrast_mod * abs(1.0 - paint_res));
    float c2p = max(0.0, 1.0 - contrast_mod * abs(paint_res));
    float c3p = 1.0 - min(1.0, c1p + c2p);
    float light = (u_lighting - 0.2) * max(c1p * 5.0 - 4.0, 0.0) + u_lighting * max(c2p * 5.0 - 4.0, 0.0);

    vec3 mixed = u_color1 * c1p + u_color2 * c2p + (c3p * u_color3);
    return (0.3 / safe_contrast) * u_color1 + (1.0 - 0.3 / safe_contrast) * mixed + vec3(light);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 uv = SCREEN_UV * resolution;
    COLOR = vec4(effect(resolution, uv), 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_speed : hint_range(0.0, 5.0) = 0.2;
uniform float u_scale : hint_range(0.1, 4.0) = 1.0;
uniform float u_frequency : hint_range(0.1, 4.0) = 1.0;
uniform float u_warp_strength : hint_range(0.0, 2.0) = 1.0;
uniform float u_mouse_influence : hint_range(0.0, 2.0) = 1.0;
uniform float u_parallax : hint_range(0.0, 2.0) = 0.5;
uniform float u_noise : hint_range(0.0, 1.0) = 0.1;
uniform vec2 u_mouse = vec2(0.5, 0.5);

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    float t = TIME * u_speed;

    vec2 p = SCREEN_UV * 2.0 - 1.0;
    p.x *= resolution.x / resolution.y;
    p += (u_mouse - vec2(0.5, 0.5)) * u_parallax;

    vec2 q = p / max(u_scale, 0.0001);
    q /= 0.5 + 0.2 * dot(q, q);
    q += 0.2 * cos(t) - 7.56;
    q += ((u_mouse - vec2(0.5, 0.5)) * 2.0 - p) * u_mouse_influence * 0.2;

    vec3 col = vec3(0.0);
    vec2 s = q;

    for (int i = 0; i < 3; i++) {
        s -= 0.01;
        vec2 r = sin(1.5 * (s.yx * u_frequency) + 2.0 * cos(s * u_frequency));
        float m0 = length(r + sin(5.0 * r.y * u_frequency - 3.0 * t + float(i)) / 4.0);

        float k_below = clamp(u_warp_strength, 0.0, 1.0);
        float k_mix = pow(k_below, 0.3);
        float gain = 1.0 + max(u_warp_strength - 1.0, 0.0);

        vec2 disp = (r - s) * k_below;
        vec2 warped = s + disp * gain;
        float m1 = length(warped + sin(5.0 * warped.y * u_frequency - 3.0 * t + float(i)) / 4.0);
        float m = mix(m0, m1, k_mix);

        col[i] = 1.0 - exp(-6.0 / exp(6.0 * m));
    }

    if (u_noise > 0.0001) {
        float n = hash12(FRAGCOORD.xy + vec2(TIME));
        col += (n - 0.5) * u_noise;
    }

    COLOR = vec4(clamp(col, 0.0, 1.0), 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_hue_shift : hint_range(-180.0, 180.0) = 0.0;
uniform float u_noise : hint_range(0.0, 0.3) = 0.0;
uniform float u_scan : hint_range(0.0, 1.0) = 0.0;
uniform float u_scan_freq : hint_range(0.0, 0.5) = 0.0;
uniform float u_warp : hint_range(0.0, 1.0) = 0.0;

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

mat2 rot(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);

    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));

    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = rot(0.6) * p * 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 rgb2yiq(vec3 c) {
    return vec3(
        dot(c, vec3(0.299, 0.587, 0.114)),
        dot(c, vec3(0.596, -0.274, -0.322)),
        dot(c, vec3(0.211, -0.523, 0.312))
    );
}

vec3 yiq2rgb(vec3 c) {
    return vec3(
        c.x + 0.956 * c.y + 0.621 * c.z,
        c.x - 0.272 * c.y - 0.647 * c.z,
        c.x - 1.106 * c.y + 1.703 * c.z
    );
}

vec3 hue_shift_rgb(vec3 col, float deg) {
    vec3 yiq = rgb2yiq(col);
    float rad = deg * PI / 180.0;
    float c = cos(rad);
    float s = sin(rad);
    vec2 iq = vec2(yiq.y * c - yiq.z * s, yiq.y * s + yiq.z * c);
    return clamp(yiq2rgb(vec3(yiq.x, iq.x, iq.y)), 0.0, 1.0);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 uv = SCREEN_UV * 2.0 - 1.0;
    uv.x *= resolution.x / resolution.y;
    uv += u_warp * vec2(sin(uv.y * 6.283 + TIME * 0.5), cos(uv.x * 6.283 + TIME * 0.5)) * 0.05;

    float t = TIME * 0.4;
    float n0 = fbm(uv * 1.3 + vec2(t, -t * 0.7));
    float n1 = fbm(uv * 2.7 - vec2(t * 0.4, t));
    float veil = smoothstep(0.25, 0.85, n0 * 0.75 + n1 * 0.45);

    vec3 deep = vec3(0.02, 0.02, 0.05);
    vec3 neon = vec3(0.18, 0.55, 0.92);
    vec3 col = mix(deep, neon, veil);
    col = hue_shift_rgb(col, u_hue_shift);

    float scan = sin(FRAGCOORD.y * u_scan_freq) * 0.5 + 0.5;
    col *= 1.0 - (scan * scan) * u_scan;

    float grain = hash12(FRAGCOORD.xy + vec2(TIME));
    col += (grain - 0.5) * u_noise;

    COLOR = vec4(clamp(col, 0.0, 1.0), 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_scale : hint_range(0.5, 4.0) = 1.0;
uniform float u_digit_size : hint_range(0.5, 3.0) = 1.5;
uniform float u_scanline_intensity : hint_range(0.0, 1.0) = 0.3;
uniform float u_glitch_amount : hint_range(0.0, 2.0) = 1.0;
uniform float u_chromatic_aberration : hint_range(0.0, 8.0) = 0.0;
uniform float u_curvature : hint_range(0.0, 0.4) = 0.2;
uniform float u_brightness : hint_range(0.0, 2.0) = 1.0;

float hash21(vec2 p) {
    p = fract(p * 234.56);
    p += dot(p, p + 34.56);
    return fract(p.x * p.y);
}

vec2 barrel(vec2 uv) {
    vec2 c = uv * 2.0 - 1.0;
    float r2 = dot(c, c);
    c *= 1.0 + u_curvature * r2;
    return c * 0.5 + 0.5;
}

float digit_cell(vec2 uv) {
    vec2 grid = vec2(30.0, 20.0);
    vec2 cell = floor(uv * grid);
    vec2 local = fract(uv * grid) * u_digit_size;

    float n = hash21(cell + floor(TIME * 2.0));
    float glyph = step(0.45, n);

    float px = floor(local.x * 5.0);
    float py = floor((1.0 - local.y) * 7.0);
    float mask = step(0.0, px) * step(px, 4.0) * step(0.0, py) * step(py, 6.0);

    float stroke = step(0.4, hash21(cell + vec2(px, py) * 0.17 + vec2(13.0, 7.0)));
    return glyph * stroke * mask;
}

vec3 terminal_color(vec2 uv) {
    float scan = 1.0 - (sin(FRAGCOORD.y * 1.7) * 0.5 + 0.5) * u_scanline_intensity;

    float glitch_band = sin(TIME * 8.0 + uv.y * 80.0);
    float disp = glitch_band * 0.01 * u_glitch_amount;

    float middle = digit_cell(uv + vec2(disp, 0.0));
    float glow = (
        digit_cell(uv + vec2(disp - 0.002, -0.002)) +
        digit_cell(uv + vec2(disp + 0.002, -0.002)) +
        digit_cell(uv + vec2(disp - 0.002, 0.002)) +
        digit_cell(uv + vec2(disp + 0.002, 0.002))
    ) * 0.25;

    vec3 col = vec3(0.85, 0.95, 1.0) * middle + vec3(0.2, 0.45, 1.0) * glow * 0.8;
    col *= scan;
    return col;
}

void fragment() {
    vec2 uv = SCREEN_UV;
    uv = barrel(uv);
    uv *= u_scale;

    vec3 col = terminal_color(uv);

    if (u_chromatic_aberration > 0.0) {
        vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
        vec2 ca = vec2(u_chromatic_aberration) / resolution;
        col.r = terminal_color(uv + ca).r;
        col.b = terminal_color(uv - ca).b;
    }

    float dither = hash21(FRAGCOORD.xy + vec2(TIME)) - 0.5;
    col += dither * 0.004;
    col *= u_brightness;

    COLOR = vec4(clamp(col, 0.0, 1.0), 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_animation_speed : hint_range(0.0, 5.0) = 1.0;
uniform float u_bend_radius : hint_range(0.5, 20.0) = 5.0;
uniform float u_bend_strength : hint_range(-2.0, 2.0) = -0.5;
uniform float u_parallax_strength : hint_range(0.0, 1.0) = 0.2;
uniform vec2 u_mouse = vec2(0.5, 0.5);

mat2 rotate2d(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

vec3 gradient_bg(vec2 uv) {
    vec3 pink = vec3(233.0, 71.0, 245.0) / 255.0;
    vec3 blue = vec3(47.0, 75.0, 162.0) / 255.0;
    float y = sin(uv.x - 0.2) * 0.3 - 0.1;
    float m = uv.y - y;
    vec3 col = vec3(0.0);
    col += mix(blue, vec3(0.0), smoothstep(0.0, 1.0, abs(m)));
    col += mix(pink, vec3(0.0), smoothstep(0.0, 1.0, abs(m - 0.8)));
    return col * 0.45;
}

float wave(vec2 uv, float offset, vec2 screen_uv, vec2 mouse_uv) {
    float t = TIME * u_animation_speed;
    float amp = sin(offset + t * 0.2) * 0.3;
    float y = sin(uv.x + offset + t * 0.1) * amp;

    vec2 d = screen_uv - mouse_uv;
    float influence = exp(-dot(d, d) * u_bend_radius);
    y += (mouse_uv.y - screen_uv.y) * influence * u_bend_strength;

    float m = uv.y - y;
    return 0.0175 / max(abs(m) + 0.01, 0.001) + 0.01;
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 uv = (2.0 * FRAGCOORD.xy - resolution.xy) / resolution.y;
    uv.y *= -1.0;

    vec2 mouse_uv = (u_mouse * 2.0 - 1.0);
    mouse_uv.x *= resolution.x / resolution.y;
    uv += (u_mouse - vec2(0.5, 0.5)) * u_parallax_strength;

    vec3 col = gradient_bg(uv);

    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float t = fi / 5.0;
        vec3 line_col = mix(vec3(0.2, 0.4, 1.0), vec3(1.0, 0.4, 0.9), t) * 0.5;

        vec2 ruv = uv * rotate2d(0.2 * log(length(uv) + 1.0));
        col += line_col * wave(ruv + vec2(0.05 * fi + 1.2, -0.2), 1.0 + 0.2 * fi, uv, mouse_uv) * 0.18;

        vec2 ruv2 = uv * rotate2d(-0.25 * log(length(uv) + 1.0));
        col += line_col * wave(ruv2 + vec2(0.06 * fi + 0.4, 0.35), 1.8 + 0.15 * fi, uv, mouse_uv) * 0.12;
    }

    COLOR = vec4(clamp(col, 0.0, 1.0), 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_density : hint_range(0.1, 4.0) = 1.0;
uniform float u_hue_shift : hint_range(0.0, 360.0) = 140.0;
uniform float u_glow_intensity : hint_range(0.0, 2.0) = 0.3;
uniform float u_twinkle_intensity : hint_range(0.0, 2.0) = 0.3;
uniform float u_rotation_speed : hint_range(-2.0, 2.0) = 0.1;
uniform vec2 u_mouse = vec2(0.5, 0.5);

#define NUM_LAYER 4.0
#define STAR_COLOR_CUTOFF 0.2

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float tri(float x) {
    return abs(fract(x) * 2.0 - 1.0);
}

float tris(float x) {
    float t = fract(x);
    return 1.0 - smoothstep(0.0, 1.0, abs(2.0 * t - 1.0));
}

float trisn(float x) {
    float t = fract(x);
    return 2.0 * (1.0 - smoothstep(0.0, 1.0, abs(2.0 * t - 1.0))) - 1.0;
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

float star_fn(vec2 uv, float flare) {
    float d = max(length(uv), 0.0001);
    float m = (0.05 * u_glow_intensity) / d;
    float rays = smoothstep(0.0, 1.0, 1.0 - abs(uv.x * uv.y * 1000.0));
    m += rays * flare * u_glow_intensity;
    mat2 rot45 = mat2(0.7071, -0.7071, 0.7071, 0.7071);
    uv *= rot45;
    rays = smoothstep(0.0, 1.0, 1.0 - abs(uv.x * uv.y * 1000.0));
    m += rays * 0.3 * flare * u_glow_intensity;
    m *= smoothstep(1.0, 0.2, d);
    return m;
}

vec3 star_layer(vec2 uv) {
    vec3 col = vec3(0.0);
    vec2 gv = fract(uv) - 0.5;
    vec2 id = floor(uv);

    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 offset = vec2(float(x), float(y));
            vec2 si = id + offset;
            float seed = hash21(si);
            float size = fract(seed * 345.32);
            float gloss_local = tri(TIME / (3.0 * seed + 1.0));
            float flare_size = smoothstep(0.9, 1.0, size) * gloss_local;

            float red = smoothstep(STAR_COLOR_CUTOFF, 1.0, hash21(si + 1.0)) + STAR_COLOR_CUTOFF;
            float blu = smoothstep(STAR_COLOR_CUTOFF, 1.0, hash21(si + 3.0)) + STAR_COLOR_CUTOFF;
            float grn = min(red, blu) * seed;
            vec3 base = vec3(red, grn, blu);

            float hue = atan(base.g - base.r, base.b - base.r) / (2.0 * PI) + 0.5;
            hue = fract(hue + u_hue_shift / 360.0);
            float sat = length(base - vec3(dot(base, vec3(0.299, 0.587, 0.114))));
            float val = max(max(base.r, base.g), base.b);
            base = hsv2rgb(vec3(hue, sat, val));

            vec2 pad = vec2(
                tris(seed * 34.0 + TIME / 10.0),
                tris(seed * 38.0 + TIME / 30.0)
            ) - 0.5;

            float star = star_fn(gv - offset - pad, flare_size);
            float twinkle = trisn(TIME + seed * 6.2831) * 0.5 + 1.0;
            twinkle = mix(1.0, twinkle, u_twinkle_intensity);
            col += star * twinkle * size * base;
        }
    }

    return col;
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 uv = SCREEN_UV * 2.0 - 1.0;
    uv.x *= resolution.x / resolution.y;

    uv += (u_mouse - vec2(0.5)) * 0.1;

    float angle = TIME * u_rotation_speed;
    mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv = rot * uv;

    vec3 col = vec3(0.0);
    for (float i = 0.0; i < 1.0; i += 1.0 / NUM_LAYER) {
        float depth = fract(i + TIME * 0.05);
        float scale = mix(20.0 * u_density, 0.5 * u_density, depth);
        float fade = depth * smoothstep(1.0, 0.9, depth);
        col += star_layer(uv * scale + i * 453.32) * fade;
    }

    COLOR = vec4(col, 1.0);
}

