shader_type canvas_item;

uniform vec3 u_color : source_color = vec3(1.0, 1.0, 1.0);
uniform vec3 u_cursor_color : source_color = vec3(1.0, 1.0, 1.0);
uniform float u_cursor_ball_size : hint_range(0.1, 8.0) = 3.0;
uniform float u_clump_factor : hint_range(0.1, 3.0) = 1.0;
uniform vec2 u_mouse = vec2(0.5, 0.5);

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float metaball_value(vec2 center, float radius, vec2 p) {
    vec2 d = p - center;
    float dist2 = max(dot(d, d), 0.0001);
    return (radius * radius) / dist2;
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 fc = FRAGCOORD.xy;

    float animation_size = 30.0;
    float scale = animation_size / resolution.y;
    vec2 coord = (fc - resolution * 0.5) * scale;
    vec2 mouse_w = (u_mouse * resolution - resolution * 0.5) * scale;

    float m1 = 0.0;
    const int ball_count = 15;
    for (int i = 0; i < ball_count; i++) {
        float idx = float(i) + 1.0;
        float st = hash11(idx * 1.7) * TAU;
        float dt_factor = mix(0.1 * PI, 0.4 * PI, hash11(idx * 2.3));
        float base_scale = mix(5.0, 10.0, hash11(idx * 3.1));
        float toggle = floor(hash11(idx * 4.2) * 2.0);
        float radius = mix(0.5, 2.0, hash11(idx * 5.3));

        float dt = TIME * 0.3 * dt_factor;
        float th = st + dt;
        float x = cos(th);
        float y = sin(th + dt * toggle);
        vec2 pos = vec2(x, y) * base_scale * u_clump_factor;
        m1 += metaball_value(pos, radius, coord);
    }

    float m2 = metaball_value(mouse_w, u_cursor_ball_size, coord);
    float total = m1 + m2;
    float f = smoothstep(-1.0, 1.0, (total - 1.3) / max(min(1.0, fwidth(total)), 0.001));

    vec3 c_final = vec3(0.0);
    if (total > 0.0) {
        float alpha1 = m1 / total;
        float alpha2 = m2 / total;
        c_final = u_color * alpha1 + u_cursor_color * alpha2;
    }

    COLOR = vec4(c_final * f, f);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_hue_shift : hint_range(0.0, 360.0) = 0.0;
uniform float u_hover_intensity : hint_range(0.0, 1.0) = 0.2;
uniform float u_rotation : hint_range(-6.2832, 6.2832) = 0.0;
uniform vec3 u_background_color : source_color = vec3(0.0, 0.0, 0.0);

vec3 rgb2yiq(vec3 c) {
    float y = dot(c, vec3(0.299, 0.587, 0.114));
    float i = dot(c, vec3(0.596, -0.274, -0.322));
    float q = dot(c, vec3(0.211, -0.523, 0.312));
    return vec3(y, i, q);
}

vec3 yiq2rgb(vec3 c) {
    float r = c.x + 0.956 * c.y + 0.621 * c.z;
    float g = c.x - 0.272 * c.y - 0.647 * c.z;
    float b = c.x - 1.106 * c.y + 1.703 * c.z;
    return vec3(r, g, b);
}

vec3 adjust_hue(vec3 color, float hue_deg) {
    float hue_rad = hue_deg * PI / 180.0;
    vec3 yiq = rgb2yiq(color);
    float cos_a = cos(hue_rad);
    float sin_a = sin(hue_rad);
    float i = yiq.y * cos_a - yiq.z * sin_a;
    float q = yiq.y * sin_a + yiq.z * cos_a;
    yiq.y = i;
    yiq.z = q;
    return yiq2rgb(yiq);
}

vec3 hash33(vec3 p3) {
    p3 = fract(p3 * vec3(0.1031, 0.11369, 0.13787));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract(vec3(
        p3.x + p3.y,
        p3.x + p3.z,
        p3.y + p3.z
    ) * p3.zyx);
}

float snoise3(vec3 p) {
    const float K1 = 0.333333333;
    const float K2 = 0.166666667;
    vec3 i = floor(p + (p.x + p.y + p.z) * K1);
    vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);
    vec3 e = step(vec3(0.0), d0 - d0.yzx);
    vec3 i1 = e * (1.0 - e.zxy);
    vec3 i2 = 1.0 - e.zxy * (1.0 - e);
    vec3 d1 = d0 - (i1 - K2);
    vec3 d2 = d0 - (i2 - K1);
    vec3 d3 = d0 - 0.5;
    vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);
    vec4 n = h * h * h * h * vec4(
        dot(d0, hash33(i)),
        dot(d1, hash33(i + i1)),
        dot(d2, hash33(i + i2)),
        dot(d3, hash33(i + 1.0))
    );
    return dot(vec4(31.316), n);
}

vec4 extract_alpha(vec3 color_in) {
    float a = max(max(color_in.r, color_in.g), color_in.b);
    return vec4(color_in / (a + 1e-5), a);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 uv = SCREEN_UV;
    vec2 centered = (uv * resolution - resolution * 0.5) / min(resolution.x, resolution.y) * 2.0;

    float s = sin(u_rotation);
    float c = cos(u_rotation);
    centered = vec2(c * centered.x - s * centered.y, s * centered.x + c * centered.y);

    centered.x += u_hover_intensity * 0.1 * sin(centered.y * 10.0 + TIME);
    centered.y += u_hover_intensity * 0.1 * sin(centered.x * 10.0 + TIME);

    vec3 color1 = adjust_hue(vec3(0.611765, 0.262745, 0.996078), u_hue_shift);
    vec3 color2 = adjust_hue(vec3(0.298039, 0.760784, 0.913725), u_hue_shift);
    vec3 color3 = adjust_hue(vec3(0.062745, 0.078431, 0.6), u_hue_shift);

    float inner_radius = 0.6;
    float noise_scale = 0.65;
    float ang = atan(centered.y, centered.x);
    float len = length(centered);
    float inv_len = len > 0.0 ? 1.0 / len : 0.0;

    float bg_luminance = dot(u_background_color, vec3(0.299, 0.587, 0.114));
    float n0 = snoise3(vec3(centered * noise_scale, TIME * 0.5)) * 0.5 + 0.5;
    float r0 = mix(mix(inner_radius, 1.0, 0.4), mix(inner_radius, 1.0, 0.6), n0);
    float d0 = distance(centered, (r0 * inv_len) * centered);
    float v0 = (1.0 / (1.0 + d0 * 10.0)) * smoothstep(r0 * 1.05, r0, len);

    float a = -TIME;
    vec2 pos = vec2(cos(a), sin(a)) * r0;
    float d = distance(centered, pos);
    float v1 = (1.5 / (1.0 + d * d * 5.0)) * (1.0 / (1.0 + d0 * 50.0));

    float v2 = smoothstep(1.0, mix(inner_radius, 1.0, n0 * 0.5), len);
    float v3 = smoothstep(inner_radius, mix(inner_radius, 1.0, 0.5), len);

    float cl = cos(ang + TIME * 2.0) * 0.5 + 0.5;
    vec3 col_base = mix(color1, color2, cl);
    vec3 dark_col = clamp((mix(color3, col_base, v0) + v1) * v2 * v3, 0.0, 1.0);
    vec3 light_col = clamp(mix(u_background_color, (col_base + v1), v0), 0.0, 1.0);
    vec3 final_col = mix(dark_col, light_col, bg_luminance);

    vec4 alpha_col = extract_alpha(final_col);
    COLOR = vec4(alpha_col.rgb * alpha_col.a, alpha_col.a);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform vec3 u_color : source_color = vec3(1.0, 1.0, 1.0);
uniform float u_speed : hint_range(0.0, 5.0) = 1.0;
uniform float u_direction : hint_range(-1.0, 1.0) = 1.0;
uniform float u_scale : hint_range(0.1, 4.0) = 1.0;
uniform float u_opacity : hint_range(0.0, 1.0) = 1.0;

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 center = resolution * 0.5;
    vec2 c = FRAGCOORD.xy;
    c = (c - center) / max(u_scale, 0.001) + center;

    float z = 0.0;
    float t = TIME * u_speed * u_direction;
    vec3 accum = vec3(0.0);

    for (float i = 1.0; i <= 48.0; i += 1.0) {
        vec3 p = z * normalize(vec3(c - 0.5 * resolution, resolution.y));
        p.z -= 4.0;
        vec3 s = p;
        float d = p.y - t;

        p.x += 0.4 * (1.0 + p.y) * sin(d + p.x * 0.1) * cos(0.34 * d + p.x * 0.05);
        float cs = cos(p.y - t);
        float sn = sin(p.y - t);
        mat2 m = mat2(cs, -sn, sn, cs);
        vec2 q = m * p.xz;

        d = abs(length(q) - 0.25 * (5.0 + s.y)) / 3.0 + 0.0008;
        z += d;

        vec3 sample_col = sin(vec3(s.y + p.z * 0.5 - length(s - p)) + vec3(2.0, 1.0, 0.0)) + 1.0;
        accum += sample_col / max(d, 0.0001);
    }

    vec3 rgb = tanh(accum / 10000.0);
    float intensity = (rgb.r + rgb.g + rgb.b) / 3.0;
    vec3 final_color = mix(rgb, intensity * u_color, step(0.0001, length(u_color - vec3(1.0))));
    float alpha = clamp(length(rgb) * u_opacity, 0.0, 1.0);

    COLOR = vec4(clamp(final_color, 0.0, 1.0), alpha);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_height : hint_range(0.5, 8.0) = 3.5;
uniform float u_base_width : hint_range(0.5, 10.0) = 5.5;
uniform float u_glow : hint_range(0.0, 3.0) = 1.0;
uniform float u_noise : hint_range(0.0, 1.0) = 0.5;
uniform float u_hue_shift : hint_range(-3.1416, 3.1416) = 0.0;
uniform float u_color_frequency : hint_range(0.1, 4.0) = 1.0;
uniform float u_bloom : hint_range(0.0, 3.0) = 1.0;

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

mat3 hue_rotation(float a) {
    float c = cos(a);
    float s = sin(a);
    mat3 w = mat3(
        vec3(0.299, 0.299, 0.299),
        vec3(0.587, 0.587, 0.587),
        vec3(0.114, 0.114, 0.114)
    );
    mat3 u = mat3(
        vec3(0.701, -0.299, -0.300),
        vec3(-0.587, 0.413, -0.588),
        vec3(-0.114, -0.114, 0.886)
    );
    mat3 v = mat3(
        vec3(0.168, 0.328, -0.497),
        vec3(-0.331, 0.035, 0.296),
        vec3(0.500, -0.500, 0.201)
    );
    return w + c * u + s * v;
}

float sd_prism(vec3 p, float h, float base_half) {
    vec3 q = vec3(abs(p.x) / base_half, abs(p.y) / h, abs(p.z) / base_half);
    float oct = (q.x + q.y + q.z - 1.0) * min(base_half, h) * 0.577350269;
    return max(oct, -p.y);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    float px_scale = 1.0 / (max(resolution.y, 1.0) * 0.1 * 3.6);
    vec2 f = (FRAGCOORD.xy - 0.5 * resolution) * px_scale;

    float z = 5.0;
    vec3 accum = vec3(0.0);
    float t = TIME * 0.5;

    for (int i = 0; i < 90; i++) {
        vec3 p = vec3(f, z);
        float c0 = cos(t + 0.3 * p.y);
        float s0 = sin(t + 0.3 * p.y);
        p.xz = mat2(c0, -s0, s0, c0) * p.xz;

        vec3 q = p;
        q.y += u_height * 0.25;

        float d = 0.1 + 0.2 * abs(sd_prism(q, max(u_height, 0.001), max(u_base_width * 0.5, 0.001)));
        z -= d;

        vec3 sample_col = sin((p.y + z) * u_color_frequency + vec3(0.0, 1.0, 2.0)) + 1.0;
        accum += sample_col / max(d, 0.0001);
    }

    vec3 col = tanh(accum * accum * (u_glow * max(u_bloom, 0.001)) / 100000.0);
    col = clamp(hue_rotation(u_hue_shift) * col, 0.0, 1.0);

    float n = hash12(FRAGCOORD.xy + vec2(TIME));
    col += (n - 0.5) * u_noise;
    col = clamp(col, 0.0, 1.0);

    COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
    COLOR = mix(c1, c2, mix_factor);
}

shader_type canvas_item;

uniform float u_shape_size : hint_range(0.1, 3.0) = 1.2;
uniform float u_roundness : hint_range(0.0, 1.0) = 0.4;
uniform float u_border_size : hint_range(0.0, 0.2) = 0.05;
uniform float u_circle_size : hint_range(0.0, 1.0) = 0.3;
uniform float u_circle_edge : hint_range(0.0, 1.0) = 0.5;
uniform vec2 u_mouse = vec2(0.5, 0.5);

vec2 coord(vec2 p, vec2 resolution) {
    p = p / resolution;
    if (resolution.x > resolution.y) {
        p.x *= resolution.x / resolution.y;
        p.x += (resolution.y - resolution.x) / resolution.y / 2.0;
    } else {
        p.y *= resolution.y / resolution.x;
        p.y += (resolution.x - resolution.y) / resolution.x / 2.0;
    }
    p -= 0.5;
    p *= vec2(-1.0, 1.0);
    return p;
}

float sd_round_rect(vec2 p, vec2 b, float r) {
    vec2 d = abs(p - 0.5) * 4.2 - b + vec2(r);
    return min(max(d.x, d.y), 0.0) + length(max(d, 0.0)) - r;
}

float sd_circle(vec2 st, vec2 center) {
    return length(st - center) * 2.0;
}

float stroke_aa(float x, float size, float w, float edge) {
    float afwidth = length(vec2(dFdx(x), dFdy(x))) * 0.70710678;
    float d = smoothstep(size - edge - afwidth, size + edge + afwidth, x + w * 0.5)
        - smoothstep(size - edge - afwidth, size + edge + afwidth, x - w * 0.5);
    return clamp(d, 0.0, 1.0);
}

float fill_fn(float x, float size, float edge) {
    return 1.0 - smoothstep(size - edge, size + edge, x);
}

void fragment() {
    vec2 resolution = 1.0 / SCREEN_PIXEL_SIZE;
    vec2 st = coord(FRAGCOORD.xy, resolution) + 0.5;
    vec2 pos_mouse = coord(u_mouse * resolution, resolution) * vec2(1.0, -1.0) + 0.5;

    float sdf_circle = fill_fn(sd_circle(st, pos_mouse), u_circle_size, u_circle_edge);
    float sdf = sd_round_rect(st, vec2(u_shape_size), u_roundness);
    sdf = stroke_aa(sdf, 0.0, u_border_size, sdf_circle) * 4.0;

    COLOR = vec4(vec3(1.0), sdf);
}

shader_type canvas_item;
uniform sampler2D input1;
uniform sampler2D input2;
uniform float mix_factor;
void fragment() {
    vec4 c1 = texture(input1, UV);
    vec4 c2 = texture(input2, UV);
